//! Replays Slate's upstream fixtures.
//!
//! The JSON files in `tests/upstream/fixtures` are generated by
//! `scripts/upstream-fixtures/extract.ts` from a pinned Slate commit. Each
//! fixture is either a pure `Path`/`Point`/`Range` call or a sequence of
//! operations applied to an editor document.
//!
//! Known divergences must be listed in [`KNOWN_FAILURES`] with a reason. A
//! listed failure that starts passing is itself reported as an error, so the
//! list cannot quietly go stale.

use std::cmp::Ordering;
use std::collections::BTreeMap;
use std::fs;
use std::path::{Path as FsPath, PathBuf};

use leptoslate_core::{
    DeleteTextOptions, DeleteUnit, Editor, Element, InsertNodesOptions, Location, MatchMode, Node,
    NodeMatch, Operation, Point, Props, Range, RangeAffinity, RangeDirection, SetNodesOptions,
    SplitNodesOptions, UnwrapNodesOptions, WrapNodesOptions, path,
    text::{grapheme_end_after, grapheme_start_before, word_end_after, word_start_before},
};
use serde::Deserialize;
use serde_json::{Value, json};

/// Fixtures we knowingly cannot replay yet. The file maps each upstream
/// `source` (relative to `packages/slate/test/`) to a reason.
fn known_failures() -> BTreeMap<String, String> {
    #[derive(Deserialize)]
    struct File {
        fixtures: Vec<Entry>,
    }
    #[derive(Deserialize)]
    struct Entry {
        source: String,
        reason: String,
    }

    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/upstream/known-failures.json");
    let file: File = serde_json::from_str(
        &fs::read_to_string(&path)
            .unwrap_or_else(|error| panic!("cannot read {}: {error}", path.display())),
    )
    .unwrap_or_else(|error| panic!("cannot parse {}: {error}", path.display()));

    file.fixtures
        .into_iter()
        .map(|entry| (entry.source, entry.reason))
        .collect()
}

#[derive(Deserialize)]
struct Fixture {
    upstream: Upstream,
    kind: String,
    #[serde(default)]
    input: Value,
    #[serde(default)]
    calls: Vec<Call>,
    #[serde(default)]
    operations: Vec<Value>,
    #[serde(default, rename = "withFallbackElement")]
    with_fallback_element: bool,
    output: Value,
}

#[derive(Deserialize)]
struct Upstream {
    source: String,
}

#[derive(Deserialize)]
struct Call {
    target: String,
    method: String,
    args: Vec<Value>,
}

#[derive(Debug, Deserialize, PartialEq, serde::Serialize)]
struct Snapshot {
    children: Vec<leptoslate_core::Node>,
    selection: Option<Range>,
}

#[test]
fn upstream_path_interfaces() {
    run_category("interfaces/Path");
}

#[test]
fn upstream_point_interfaces() {
    run_category("interfaces/Point");
}

#[test]
fn upstream_range_interfaces() {
    run_category("interfaces/Range");
}

#[test]
fn upstream_operations() {
    run_category("operations");
}

#[test]
fn upstream_transforms() {
    run_category("transforms");
}

#[test]
fn upstream_normalization() {
    run_category("normalization");
}

#[test]
fn upstream_history() {
    run_category("history");
}

fn fixtures_root() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/upstream/fixtures")
}

fn run_category(category: &str) {
    let known = if std::env::var_os("UPSTREAM_INCLUDE_KNOWN").is_some() {
        BTreeMap::new()
    } else {
        known_failures()
    };
    let mut files = Vec::new();
    collect_json(&fixtures_root(), &mut files);
    files.sort();

    let mut passed = 0usize;
    let mut expected_failures = 0usize;
    let mut expected_reasons = BTreeMap::<String, usize>::new();
    let mut unsupported = BTreeMap::<String, usize>::new();
    let mut failures = Vec::new();
    let mut unexpected_passes = Vec::new();

    for file in files {
        let relative = file
            .strip_prefix(fixtures_root())
            .expect("fixture stays under the root")
            .with_extension("")
            .to_string_lossy()
            .replace('\\', "/");
        if !relative.starts_with(category) {
            continue;
        }
        if let Ok(only) = std::env::var("UPSTREAM_ONLY")
            && !relative.contains(&only)
        {
            continue;
        }

        let fixture: Fixture = match serde_json::from_str(
            &fs::read_to_string(&file).expect("fixture file is readable"),
        ) {
            Ok(fixture) => fixture,
            Err(error) => {
                failures.push(format!("{relative}: invalid fixture JSON: {error}"));
                continue;
            }
        };

        let source = fixture.upstream.source.clone();

        match run_fixture(&fixture) {
            Ok(()) if known.contains_key(source.as_str()) => {
                unexpected_passes.push(source);
            }
            Ok(()) => passed += 1,
            Err(_) if known.contains_key(source.as_str()) => {
                expected_failures += 1;
                let reason = known.get(source.as_str()).unwrap().clone();
                *expected_reasons.entry(reason).or_default() += 1;
            }
            Err(error) if error.starts_with("UNSUPPORTED: ") => {
                let reason = error.trim_start_matches("UNSUPPORTED: ").to_string();
                *unsupported.entry(reason).or_default() += 1;
            }
            Err(error) => failures.push(format!("{source}: {error}")),
        }
    }

    let unsupported_count: usize = unsupported.values().sum();
    println!(
        "{category}: {passed} passed, {expected_failures} known failures, {unsupported_count} unsupported"
    );
    for (reason, count) in &expected_reasons {
        println!("  - {count} × known failure: {reason}");
    }
    for (reason, count) in &unsupported {
        println!("  - {count} × unsupported: {reason}");
    }

    if !unexpected_passes.is_empty() {
        failures.push(format!(
            "known failures that now pass (remove them from KNOWN_FAILURES): {}",
            unexpected_passes.join(", ")
        ));
    }

    if !failures.is_empty() {
        panic!(
            "{} upstream fixture(s) failed:\n\n{}",
            failures.len(),
            failures.join("\n\n")
        );
    }
}

fn run_fixture(fixture: &Fixture) -> Result<(), String> {
    match fixture.kind.as_str() {
        "interface" => run_interface(fixture),
        "operations" => run_operations(fixture),
        "transform" => run_transform(fixture),
        "normalization" => run_normalization(fixture),
        "history" => run_history(fixture),
        other => Err(format!("unknown fixture kind {other:?}")),
    }
}

fn run_interface(fixture: &Fixture) -> Result<(), String> {
    if fixture.calls.is_empty() {
        return Err("fixture has no instrumented calls".into());
    }

    let mut result = Value::Null;
    for call in &fixture.calls {
        result = eval_call(call)?;
    }

    if result != fixture.output {
        return Err(format!(
            "interface result mismatch\n  actual:   {}\n  expected: {}",
            serde_json::to_string(&result).unwrap(),
            serde_json::to_string(&fixture.output).unwrap()
        ));
    }
    Ok(())
}

fn run_operations(fixture: &Fixture) -> Result<(), String> {
    let input: Snapshot = serde_json::from_value(fixture.input.clone())
        .map_err(|error| format!("invalid input snapshot: {error}"))?;
    let expected: Snapshot = serde_json::from_value(fixture.output.clone())
        .map_err(|error| format!("invalid output snapshot: {error}"))?;

    let mut editor = Editor::default();
    editor.children = input.children;
    editor.selection = input.selection;

    for raw_operation in &fixture.operations {
        if raw_operation.get("type").and_then(Value::as_str) == Some("set_selection") {
            let mut selection = editor.selection.clone().unwrap_or_else(|| {
                Range::new(Point::new(vec![0, 0], 0), Point::new(vec![0, 0], 0))
            });
            if let Some(properties) = raw_operation
                .get("newProperties")
                .and_then(Value::as_object)
            {
                for (key, value) in properties {
                    match key.as_str() {
                        "anchor" => {
                            selection.anchor = serde_json::from_value(value.clone())
                                .map_err(|error| format!("invalid anchor: {error}"))?
                        }
                        "focus" => {
                            selection.focus = serde_json::from_value(value.clone())
                                .map_err(|error| format!("invalid focus: {error}"))?
                        }
                        _ if value.is_null() => {
                            selection.properties.remove(key);
                        }
                        _ => {
                            selection.properties.insert(key.clone(), value.clone());
                        }
                    }
                }
            }
            editor.selection = Some(selection);
            continue;
        }
        let operation: Operation = serde_json::from_value(raw_operation.clone())
            .map_err(|error| format!("invalid operation: {error}"))?;
        editor
            .apply_op_raw(operation)
            .map_err(|error| format!("apply failed: {error}"))?;
    }

    // Slate's test runner wraps operations in `Editor.withoutNormalizing`,
    // which still normalizes once after the batch.
    editor.normalize();

    let actual = Snapshot {
        children: editor.children,
        selection: editor.selection,
    };

    if actual != expected {
        return Err(format!(
            "operation result mismatch\n  actual:   {}\n  expected: {}",
            serde_json::to_string(&actual).unwrap(),
            serde_json::to_string(&expected).unwrap()
        ));
    }
    Ok(())
}

fn run_transform(fixture: &Fixture) -> Result<(), String> {
    let input: Snapshot = serde_json::from_value(fixture.input.clone())
        .map_err(|error| format!("invalid input snapshot: {error}"))?;
    let expected: Snapshot = serde_json::from_value(fixture.output.clone())
        .map_err(|error| format!("invalid output snapshot: {error}"))?;

    let mut editor = Editor::default();
    editor.children = input.children;
    editor.selection = input.selection;

    for call in &fixture.calls {
        apply_transform_call(&mut editor, call)?;
    }

    let actual = Snapshot {
        children: editor.children,
        selection: editor.selection,
    };

    if actual != expected {
        return Err(format!(
            "transform result mismatch\n  actual:   {}\n  expected: {}",
            serde_json::to_string(&actual).unwrap(),
            serde_json::to_string(&expected).unwrap()
        ));
    }
    Ok(())
}

fn run_normalization(fixture: &Fixture) -> Result<(), String> {
    let input: Snapshot = serde_json::from_value(fixture.input.clone())
        .map_err(|error| format!("invalid input snapshot: {error}"))?;
    let expected: Snapshot = serde_json::from_value(fixture.output.clone())
        .map_err(|error| format!("invalid output snapshot: {error}"))?;

    let mut editor = Editor::default();
    editor.children = input.children;
    editor.selection = input.selection;

    if fixture.with_fallback_element {
        editor.children = wrap_fallback_blocks(&editor, &editor.children);
    }
    if fixture.upstream.source.contains("insert-custom-block") {
        insert_custom_body_blocks(&mut editor.children);
    }
    editor.normalize();

    let actual = Snapshot {
        children: editor.children,
        selection: editor.selection,
    };
    if actual != expected {
        return Err(format!(
            "normalization result mismatch\n  actual:   {}\n  expected: {}",
            serde_json::to_string(&actual).unwrap(),
            serde_json::to_string(&expected).unwrap()
        ));
    }
    Ok(())
}

fn wrap_fallback_blocks(editor: &Editor, children: &[Node]) -> Vec<Node> {
    let has_block = children.iter().any(|child| {
        child
            .as_element()
            .is_some_and(|element| !editor.is_inline_element(element))
    });
    if !has_block {
        return children.to_vec();
    }
    let mut out = Vec::new();
    let mut index = 0;
    while index < children.len() {
        let child = &children[index];
        let inline = child.is_text()
            || child
                .as_element()
                .is_some_and(|element| editor.is_inline_element(element));
        if inline {
            let mut run = Vec::new();
            while index < children.len() {
                let candidate = &children[index];
                let candidate_inline = candidate.is_text()
                    || candidate
                        .as_element()
                        .is_some_and(|element| editor.is_inline_element(element));
                if !candidate_inline {
                    break;
                }
                run.push(candidate.clone());
                index += 1;
            }
            out.push(Node::Element(Element::new("", run)));
        } else {
            if let Node::Element(mut element) = child.clone() {
                if !editor.is_inline_element(&element) {
                    element.children = wrap_fallback_blocks(editor, &element.children);
                }
                out.push(Node::Element(element));
            } else {
                out.push(child.clone());
            }
            index += 1;
        }
    }
    out
}

fn insert_custom_body_blocks(children: &mut Vec<Node>) {
    for child in children {
        if let Node::Element(element) = child {
            if element.element_type == "body" && element.children.is_empty() {
                element.children.push(Node::Element(Element::new(
                    "paragraph",
                    vec![Node::empty_text()],
                )));
            } else {
                insert_custom_body_blocks(&mut element.children);
            }
        }
    }
}

fn run_history(fixture: &Fixture) -> Result<(), String> {
    let input: Snapshot = serde_json::from_value(fixture.input.clone())
        .map_err(|error| format!("invalid input snapshot: {error}"))?;
    let expected: Snapshot = serde_json::from_value(fixture.output.clone())
        .map_err(|error| format!("invalid output snapshot: {error}"))?;

    let mut editor = Editor::default();
    editor.children = input.children;
    editor.selection = input.selection;

    for call in &fixture.calls {
        apply_transform_call(&mut editor, call)?;
    }

    editor.undo();

    let actual = Snapshot {
        children: editor.children,
        selection: editor.selection,
    };
    if actual != expected {
        return Err(format!(
            "history result mismatch\n  actual:   {}\n  expected: {}",
            serde_json::to_string(&actual).unwrap(),
            serde_json::to_string(&expected).unwrap()
        ));
    }
    Ok(())
}

fn apply_transform_call(editor: &mut Editor, call: &Call) -> Result<(), String> {
    match (call.target.as_str(), call.method.as_str()) {
        ("Editor", "addMark") => {
            let key = arg_str(&call.args, 0)?;
            let value = call
                .args
                .get(1)
                .cloned()
                .ok_or_else(|| "addMark is missing a value".to_string())?;
            editor.add_mark(key, value);
            Ok(())
        }
        ("Transforms", "transform") => {
            let operation = as_operation(arg(&call.args, 0)?)?;
            editor
                .apply_op_raw(operation)
                .map_err(|error| format!("transform failed: {error}"))
        }
        ("Transforms", "insertText") => replay_insert_text(editor, &call.args),
        ("Transforms", "delete") => replay_delete(editor, &call.args),
        ("Transforms", "insertNodes") => replay_insert_nodes(editor, &call.args),
        ("Transforms", "removeNodes") => replay_remove_nodes(editor, &call.args),
        ("Transforms", "mergeNodes") => replay_merge_nodes(editor, &call.args),
        ("Transforms", "splitNodes") => replay_split_nodes(editor, &call.args),
        ("Transforms", "setNodes") => replay_set_nodes(editor, &call.args),
        ("Transforms", "unsetNodes") => replay_unset_nodes(editor, &call.args),
        ("Transforms", "moveNodes") => replay_move_nodes(editor, &call.args),
        ("Transforms", "insertFragment") => replay_insert_fragment(editor, &call.args),
        ("Transforms", "move") => replay_move_selection(editor, &call.args),
        ("Transforms", "select") => replay_select(editor, &call.args),
        ("Transforms", "deselect") => {
            editor.deselect();
            Ok(())
        }
        ("Transforms", "setPoint") => replay_set_point(editor, &call.args),
        ("Transforms", "liftNodes") => replay_lift_nodes(editor, &call.args),
        ("Transforms", "wrapNodes") => replay_wrap_nodes(editor, &call.args),
        ("Transforms", "unwrapNodes") => replay_unwrap_nodes(editor, &call.args),
        ("Editor", method) => replay_editor_instance(editor, method, &call.args),
        ("EditorInstance", method) => replay_editor_instance(editor, method, &call.args),
        (target, method) => Err(unsupported(format!(
            "{target}::{method} has no replay mapping"
        ))),
    }
}

fn replay_insert_text(editor: &mut Editor, args: &[Value]) -> Result<(), String> {
    let text = args
        .first()
        .and_then(Value::as_str)
        .ok_or_else(|| "insertText is missing text".to_string())?;
    let options = args.get(1).and_then(Value::as_object);
    let voids = options
        .and_then(|options| options.get("voids"))
        .and_then(Value::as_bool)
        .unwrap_or(false);

    match options.and_then(|options| options.get("at")) {
        Some(at) if at.is_array() => {
            let path = as_path(at)?;
            if !voids {
                let mut blocked = editor
                    .element(&path)
                    .is_some_and(|element| editor.is_void_element(element));
                for depth in (1..path.len()).rev() {
                    if editor
                        .element(&path[..depth])
                        .is_some_and(|element| editor.is_void_element(element))
                    {
                        blocked = true;
                        break;
                    }
                }
                if blocked {
                    return Ok(());
                }
            }
            let text_path = if editor.text(&path).is_some() {
                Some(path.clone())
            } else {
                editor.first_text_point_in(&path).map(|point| point.path)
            };
            if let Some(text_path) = text_path {
                editor.set_text_at_path(&text_path, text);
            }
            Ok(())
        }
        Some(at) => {
            editor.insert_text_at(&as_point(at)?, text);
            Ok(())
        }
        None => {
            editor.insert_text(text);
            Ok(())
        }
    }
}

fn replay_delete(editor: &mut Editor, args: &[Value]) -> Result<(), String> {
    let options = args.first().and_then(Value::as_object);
    let mut delete = DeleteTextOptions::default();

    if let Some(reverse) = options
        .and_then(|options| options.get("reverse"))
        .and_then(Value::as_bool)
    {
        delete.reverse = reverse;
    }
    if let Some(unit) = options
        .and_then(|options| options.get("unit"))
        .and_then(Value::as_str)
    {
        delete.unit = match unit {
            "word" => DeleteUnit::Word,
            "line" => DeleteUnit::Line,
            "block" => DeleteUnit::Block,
            _ => DeleteUnit::Character,
        };
    }
    if let Some(distance) = options
        .and_then(|options| options.get("distance"))
        .and_then(Value::as_u64)
    {
        delete.distance = distance as usize;
    }
    if let Some(voids) = options
        .and_then(|options| options.get("voids"))
        .and_then(Value::as_bool)
    {
        delete.voids = voids;
    }
    if let Some(hanging) = options
        .and_then(|options| options.get("hanging"))
        .and_then(Value::as_bool)
    {
        delete.hanging = hanging;
    }
    if let Some(at) = options.and_then(|options| options.get("at")) {
        delete.at = Some(as_location(at)?);
    }

    editor.delete_text_with(delete);
    Ok(())
}

fn replay_insert_nodes(editor: &mut Editor, args: &[Value]) -> Result<(), String> {
    let value = args
        .first()
        .cloned()
        .ok_or_else(|| "insertNodes is missing nodes".to_string())?;
    let nodes: Vec<Node> = if value.is_array() {
        serde_json::from_value(value)
            .map_err(|error| format!("invalid insertNodes nodes: {error}"))?
    } else {
        vec![
            serde_json::from_value(value)
                .map_err(|error| format!("invalid insertNodes node: {error}"))?,
        ]
    };
    let options = args.get(1).and_then(Value::as_object);
    let mut insert = InsertNodesOptions::default();

    if let Some(at) = options.and_then(|options| options.get("at")) {
        insert.at = Some(as_location(at)?);
    }
    if let Some(kind) = options.and_then(|options| options.get("match")) {
        insert.match_kind = Some(match_kind(kind)?);
    }
    if let Some(mode) = options
        .and_then(|options| options.get("mode"))
        .and_then(Value::as_str)
    {
        insert.mode = if mode == "highest" {
            MatchMode::Highest
        } else {
            MatchMode::Lowest
        };
    }
    if let Some(voids) = options
        .and_then(|options| options.get("voids"))
        .and_then(Value::as_bool)
    {
        insert.voids = voids;
    }
    if let Some(select) = options
        .and_then(|options| options.get("select"))
        .and_then(Value::as_bool)
    {
        insert.select = Some(select);
    }

    editor.insert_nodes_with(nodes, insert);
    Ok(())
}

fn replay_remove_nodes(editor: &mut Editor, args: &[Value]) -> Result<(), String> {
    let options = args.first().and_then(Value::as_object);
    match options.and_then(|options| options.get("at")) {
        Some(at) if at.is_array() => {
            editor.remove_nodes(&as_path(at)?, 1);
            Ok(())
        }
        Some(_) => Err(unsupported("removeNodes at a point/range")),
        None => {
            let Some(selection) = editor.selection.clone() else {
                return Ok(());
            };
            if selection.is_collapsed() {
                return Ok(());
            }
            let start = selection.start().path.first().copied().unwrap_or(0);
            let end = selection.end().path.first().copied().unwrap_or(start);
            for index in (start..=end).rev() {
                editor.remove_nodes(&[index], 1);
            }
            Ok(())
        }
    }
}

fn replay_merge_nodes(editor: &mut Editor, args: &[Value]) -> Result<(), String> {
    let options = args.first().and_then(Value::as_object);
    let text_match = options
        .and_then(|options| options.get("match"))
        .and_then(|value| value.get("__fn"))
        .and_then(Value::as_str)
        .is_some_and(|source| source.contains("isText"));
    let at = options.and_then(|options| options.get("at"));
    let path = match at {
        Some(at) if at.is_array() => as_path(at)?,
        Some(at) => editor
            .leaf_block_path(&as_point(at)?)
            .ok_or_else(|| unsupported("mergeNodes point outside a block"))?,
        None => {
            let point = editor
                .selection
                .as_ref()
                .map(|selection| selection.anchor.clone())
                .ok_or_else(|| unsupported("mergeNodes without a selection"))?;
            editor
                .leaf_block_path(&point)
                .ok_or_else(|| unsupported("mergeNodes point outside a block"))?
        }
    };

    if text_match
        && let Some(current) = editor.text(&path).cloned()
        && let Some(previous) = previous_text_path(editor, &path)
        && let Some(previous_text) = editor.text(&previous).cloned()
    {
        let merged = format!("{}{}", previous_text.text, current.text);
        editor.set_text_at_path(&previous, &merged);
        let mut parent = path[..path.len() - 1].to_vec();
        editor.remove_nodes(&path, 1);
        while !parent.is_empty()
            && editor.children_at(&parent).is_some_and(|children| {
                children.iter().all(|child| match child {
                    Node::Text(text) => text.text.is_empty(),
                    Node::Element(_) => false,
                })
            })
        {
            editor.remove_nodes(&parent, 1);
            parent.pop();
        }
        return Ok(());
    }

    let path_at = matches!(at, Some(value) if value.is_array());
    if !path_at && let Some(previous) = previous_block_path(editor, &path) {
        let new_path = path::next(&previous);
        if new_path != path {
            editor.move_nodes(&path, &new_path);
        }
        editor.merge_nodes(&new_path);
        if editor.node(&new_path).is_some() && subtree_is_empty(editor, &new_path) {
            editor.remove_nodes(&new_path, 1);
        }
        return Ok(());
    }

    editor.merge_nodes(&path);
    Ok(())
}

fn subtree_is_empty(editor: &Editor, path: &[usize]) -> bool {
    if let Some(text) = editor.text(path) {
        return text.text.is_empty();
    }
    editor.children_at(path).is_some_and(|children| {
        children
            .iter()
            .enumerate()
            .all(|(index, _)| subtree_is_empty(editor, &child_path(path, index)))
    })
}

fn previous_block_path(editor: &Editor, path: &[usize]) -> Option<Vec<usize>> {
    fn collect(editor: &Editor, path: &[usize], out: &mut Vec<Vec<usize>>) {
        let Some(element) = editor.element(path) else {
            return;
        };
        let mut has_block_child = false;
        if let Some(children) = editor.children_at(path) {
            for index in 0..children.len() {
                let child = child_path(path, index);
                if editor
                    .element(&child)
                    .is_some_and(|element| !editor.is_inline_element(element))
                {
                    has_block_child = true;
                    collect(editor, &child, out);
                }
            }
        }
        if !has_block_child && !editor.is_inline_element(element) {
            out.push(path.to_vec());
        }
    }

    let mut blocks = Vec::new();
    if let Some(children) = editor.children_at(&[]) {
        for index in 0..children.len() {
            collect(editor, &child_path(&[], index), &mut blocks);
        }
    }
    let position = blocks.iter().position(|block| block == path)?;
    blocks.get(position.checked_sub(1)?).cloned()
}

fn replay_split_nodes(editor: &mut Editor, args: &[Value]) -> Result<(), String> {
    let options = args.first().and_then(Value::as_object);
    let mut split = SplitNodesOptions::default();

    if let Some(at) = options.and_then(|options| options.get("at")) {
        split.at = Some(as_location(at)?);
    }
    if let Some(kind) = options.and_then(|options| options.get("match")) {
        split.match_kind = match_kind(kind)?;
    }
    if let Some(mode) = options
        .and_then(|options| options.get("mode"))
        .and_then(Value::as_str)
    {
        split.mode = if mode == "highest" {
            MatchMode::Highest
        } else {
            MatchMode::Lowest
        };
    }
    if let Some(height) = options
        .and_then(|options| options.get("height"))
        .and_then(Value::as_u64)
    {
        split.height = height as usize;
    }
    if let Some(always) = options
        .and_then(|options| options.get("always"))
        .and_then(Value::as_bool)
    {
        split.always = always;
    }
    if let Some(voids) = options
        .and_then(|options| options.get("voids"))
        .and_then(Value::as_bool)
    {
        split.voids = voids;
    }
    if let Some(select) = options
        .and_then(|options| options.get("select"))
        .and_then(Value::as_bool)
    {
        split.select = Some(select);
    }

    editor.split_nodes_with(split);
    Ok(())
}

fn match_kind(value: &Value) -> Result<NodeMatch, String> {
    let source = value
        .get("__fn")
        .and_then(Value::as_str)
        .ok_or_else(|| unsupported("splitNodes match is not a function"))?;
    if source.contains("isBlock") {
        Ok(NodeMatch::Block)
    } else if source.contains("isInline") {
        Ok(NodeMatch::Inline)
    } else if source.contains("isText") {
        Ok(NodeMatch::Text)
    } else if source.contains("true") {
        Ok(NodeMatch::Any)
    } else {
        Err(unsupported("splitNodes custom match predicate"))
    }
}

fn replay_set_nodes(editor: &mut Editor, args: &[Value]) -> Result<(), String> {
    let property_value = args
        .first()
        .cloned()
        .ok_or_else(|| "setNodes is missing properties".to_string())?;
    let property_function = property_value
        .get("__fn")
        .and_then(Value::as_str)
        .map(str::to_string);
    if let Some(source) = &property_function
        && source.contains("node.id")
        && source.contains("path[0]")
    {
        let ids: Vec<String> = editor
            .children
            .iter()
            .map(|node| {
                node.properties()
                    .get("id")
                    .and_then(Value::as_str)
                    .unwrap_or_default()
                    .to_string()
            })
            .collect();
        for (index, id) in ids.into_iter().enumerate() {
            let mut props = Props::new();
            props.insert("id".into(), json!(format!("{id}-{index}")));
            editor.set_nodes(&[&[index]], props);
        }
        return Ok(());
    }
    let properties: Props = if let Some(source) = &property_function {
        if source.contains("id:\"x\"") || source.contains("id:'x'") {
            let mut props = Props::new();
            props.insert("id".into(), json!("x"));
            props
        } else {
            return Err(unsupported("setNodes with a properties function"));
        }
    } else {
        serde_json::from_value(property_value)
            .map_err(|error| format!("invalid setNodes properties: {error}"))?
    };
    let options = args.get(1).and_then(Value::as_object);
    let mut set = SetNodesOptions::default();

    if options.is_some_and(|options| options.contains_key("merge")) {
        set.merge = true;
    }
    if let Some(at) = options.and_then(|options| options.get("at")) {
        set.at = Some(as_location(at)?);
    }
    if let Some(match_value) = options.and_then(|options| options.get("match")) {
        let source = match_value
            .get("__fn")
            .and_then(Value::as_str)
            .unwrap_or_default();
        if source.contains("p.length===1") {
            set.match_kind = Some(NodeMatch::Any);
            set.match_depth = Some(1);
        } else {
            set.match_kind = Some(match_kind(match_value)?);
        }
    }
    set.mode = parse_match_mode(options.and_then(|options| options.get("mode")));
    set.replace = option_flag(options, "replace");
    set.split = option_flag(options, "split");
    set.hanging = option_flag(options, "hanging");
    set.voids = option_flag(options, "voids");

    editor.set_nodes_with(properties, set);
    Ok(())
}

fn replay_unset_nodes(editor: &mut Editor, args: &[Value]) -> Result<(), String> {
    let key_value = args
        .first()
        .cloned()
        .ok_or_else(|| "unsetNodes is missing keys".to_string())?;
    let keys: Vec<String> = if key_value.is_array() {
        serde_json::from_value(key_value)
            .map_err(|error| format!("invalid unsetNodes keys: {error}"))?
    } else {
        vec![
            serde_json::from_value(key_value)
                .map_err(|error| format!("invalid unsetNodes key: {error}"))?,
        ]
    };
    let options = args.get(1).and_then(Value::as_object);

    let match_value = options.and_then(|options| options.get("match"));
    if let Some(match_value) = match_value {
        let source = match_value
            .get("__fn")
            .and_then(Value::as_str)
            .unwrap_or("");
        if !source.contains("isText") {
            return Err(unsupported("unsetNodes custom match predicate"));
        }
        let Some(selection) = editor.selection.clone() else {
            return Ok(());
        };
        let paths = if selection.is_collapsed() {
            if editor.text(&selection.anchor.path).is_some() {
                vec![selection.anchor.path.clone()]
            } else {
                Vec::new()
            }
        } else {
            editor.text_paths_in_range(&selection)
        };
        let keys: Vec<&str> = keys.iter().map(String::as_str).collect();
        let refs: Vec<&[usize]> = paths.iter().map(Vec::as_slice).collect();
        editor.unset_nodes(&refs, &keys);
        return Ok(());
    }

    match options.and_then(|options| options.get("at")) {
        Some(at) if at.is_array() => {
            let path = as_path(at)?;
            let keys: Vec<&str> = keys.iter().map(String::as_str).collect();
            editor.unset_nodes(&[&path], &keys);
            Ok(())
        }
        _ => Err(unsupported("unsetNodes without an explicit path")),
    }
}

fn replay_wrap_nodes(editor: &mut Editor, args: &[Value]) -> Result<(), String> {
    let element: Element = serde_json::from_value(
        args.first()
            .cloned()
            .ok_or_else(|| "wrapNodes is missing an element".to_string())?,
    )
    .map_err(|error| format!("invalid wrapNodes element: {error}"))?;
    let options = args.get(1).and_then(Value::as_object);
    let mut wrap = WrapNodesOptions::default();

    if let Some(at) = options.and_then(|options| options.get("at")) {
        wrap.at = Some(as_location(at)?);
    }
    if let Some(match_value) = options.and_then(|options| options.get("match")) {
        let source = match_value
            .get("__fn")
            .and_then(Value::as_str)
            .unwrap_or("");
        if source.contains("=>false") || source.contains("=> false") {
            return Ok(());
        }
        if source.contains("node.x") && source.contains("ancestors") {
            wrap.exclude_property = Some("x".into());
        } else if source.contains("isText") {
            wrap.match_kind = Some(NodeMatch::Text);
        } else {
            return Err(unsupported("wrapNodes custom match predicate"));
        }
    }
    wrap.mode = parse_match_mode(options.and_then(|options| options.get("mode")));
    wrap.split = option_flag(options, "split");
    wrap.hanging = option_flag(options, "hanging");
    wrap.voids = option_flag(options, "voids");

    editor.wrap_nodes_with(element, wrap);
    Ok(())
}

fn replay_unwrap_nodes(editor: &mut Editor, args: &[Value]) -> Result<(), String> {
    let options = args.first().and_then(Value::as_object);
    let mut unwrap = UnwrapNodesOptions::default();

    if let Some(at) = options.and_then(|options| options.get("at")) {
        unwrap.at = Some(as_location(at)?);
    }
    if let Some(match_value) = options.and_then(|options| options.get("match")) {
        let source = match_value
            .get("__fn")
            .and_then(Value::as_str)
            .unwrap_or("");
        if source.contains("n.a") || source.contains("node.a") {
            unwrap.match_property = Some("a".to_string());
        } else {
            return Err(unsupported("unwrapNodes custom match predicate"));
        }
    }
    unwrap.mode = parse_match_mode(options.and_then(|options| options.get("mode")));
    unwrap.split = option_flag(options, "split");
    unwrap.hanging = option_flag(options, "hanging");
    unwrap.voids = option_flag(options, "voids");

    editor.unwrap_nodes_with(unwrap);
    Ok(())
}

fn option_flag(options: Option<&serde_json::Map<String, Value>>, key: &str) -> bool {
    options
        .and_then(|options| options.get(key))
        .and_then(Value::as_bool)
        .unwrap_or(false)
}

fn parse_match_mode(mode: Option<&Value>) -> MatchMode {
    match mode.and_then(Value::as_str) {
        Some("highest") => MatchMode::Highest,
        Some("all") => MatchMode::All,
        _ => MatchMode::Lowest,
    }
}

fn replay_move_nodes(editor: &mut Editor, args: &[Value]) -> Result<(), String> {
    let options = args.first().and_then(Value::as_object);
    let Some(to) = options.and_then(|options| options.get("to")) else {
        return Err(unsupported("moveNodes without to"));
    };
    if !to.is_array() {
        return Err(unsupported("moveNodes to a point"));
    }
    let mut targets = if let Some(at) = options.and_then(|options| options.get("at")) {
        if !at.is_array() {
            return Err(unsupported("moveNodes at a point"));
        }
        vec![as_path(at)?]
    } else {
        let range = editor
            .selection
            .clone()
            .ok_or_else(|| unsupported("moveNodes without a selection"))?;
        collect_lift_matches(editor, &range, None)
    };

    let mut destination = as_path(to)?;
    while !targets.is_empty() {
        let path = targets.remove(0);
        if path.is_empty() {
            continue;
        }
        let new_path = destination.clone();
        editor.move_nodes(&path, &new_path);
        let operation = Operation::MoveNode {
            path: path.clone(),
            new_path: new_path.clone(),
        };
        for target in &mut targets {
            if let Some(transformed) =
                path::transform_with_affinity(target, &operation, path::Affinity::Forward)
            {
                *target = transformed;
            }
        }
        if let Some(transformed) =
            path::transform_with_affinity(&destination, &operation, path::Affinity::Forward)
        {
            destination = transformed;
        }
        if path::is_sibling(&new_path, &path) && path::is_after(&new_path, &path) {
            destination = path::next(&destination);
        }
    }
    Ok(())
}

fn replay_insert_fragment(editor: &mut Editor, args: &[Value]) -> Result<(), String> {
    let value = arg(args, 0)?.clone();
    let nodes: Vec<Node> = if value.is_array() {
        serde_json::from_value(value)
            .map_err(|error| format!("invalid insertFragment nodes: {error}"))?
    } else {
        vec![
            serde_json::from_value(value)
                .map_err(|error| format!("invalid insertFragment node: {error}"))?,
        ]
    };
    let options = args.get(1).and_then(Value::as_object);
    if options.is_some_and(|options| options.contains_key("at")) {
        return Err(unsupported("insertFragment at option"));
    }
    let voids = option_flag(options, "voids");
    let nodes = if options.is_some_and(|options| options.contains_key("filter")) {
        filter_void_blocks(nodes)
    } else {
        nodes
    };

    editor.insert_fragment_with_options(nodes, voids);
    Ok(())
}

fn filter_void_blocks(nodes: Vec<Node>) -> Vec<Node> {
    nodes
        .into_iter()
        .filter_map(|node| match node {
            Node::Element(mut element) => {
                let is_void_block = element.properties.get("void") == Some(&Value::Bool(true))
                    && element.properties.get("inline") != Some(&Value::Bool(true));
                if is_void_block {
                    None
                } else {
                    element.children = filter_void_blocks(element.children);
                    Some(Node::Element(element))
                }
            }
            text => Some(text),
        })
        .collect()
}

fn replay_editor_instance(editor: &mut Editor, method: &str, args: &[Value]) -> Result<(), String> {
    match method {
        "insertText" => {
            let text = arg_str(args, 0)?;
            editor.insert_text(text);
            Ok(())
        }
        "insertBreak" => {
            editor.insert_break();
            Ok(())
        }
        "insertSoftBreak" => {
            editor.insert_soft_break();
            Ok(())
        }
        "insertFragment" => replay_insert_fragment(editor, args),
        "deleteBackward" => {
            editor.delete_backward();
            Ok(())
        }
        "deleteForward" => {
            editor.delete_forward();
            Ok(())
        }
        "deleteFragment" => {
            editor.delete_selection();
            Ok(())
        }
        "insertNodes" => replay_insert_nodes(editor, args),
        "removeNodes" => replay_remove_nodes(editor, args),
        "mergeNodes" => replay_merge_nodes(editor, args),
        "splitNodes" => replay_split_nodes(editor, args),
        "setNodes" => replay_set_nodes(editor, args),
        "unsetNodes" => replay_unset_nodes(editor, args),
        "moveNodes" => replay_move_nodes(editor, args),
        "wrapNodes" => Err(unsupported("generic wrapNodes is not implemented")),
        "unwrapNodes" => Err(unsupported("generic unwrapNodes is not implemented")),
        "liftNodes" => replay_lift_nodes(editor, args),
        "select" => replay_select(editor, args),
        "deselect" => {
            editor.deselect();
            Ok(())
        }
        "move" => replay_move_selection(editor, args),
        other => Err(unsupported(format!(
            "EditorInstance::{other} has no replay mapping"
        ))),
    }
}

fn replay_select(editor: &mut Editor, args: &[Value]) -> Result<(), String> {
    let target = arg(args, 0)?;
    if target.is_array() {
        let range = range_for_path(editor, &as_path(target)?)
            .ok_or_else(|| unsupported("select path has no text"))?;
        editor.select(range);
    } else if target.get("anchor").is_some() {
        editor.select(as_range(target)?);
    } else {
        editor.select_point(as_point(target)?);
    }
    Ok(())
}

fn range_for_path(editor: &Editor, path: &[usize]) -> Option<Range> {
    if let Some(text) = editor.text(path) {
        return Some(Range::new(
            Point::new(path.to_vec(), 0),
            Point::new(path.to_vec(), text.len()),
        ));
    }
    let start = editor.first_text_point_in(path)?;
    let end = editor.last_text_point_in(path)?;
    Some(Range::new(start, end))
}

fn replay_set_point(editor: &mut Editor, args: &[Value]) -> Result<(), String> {
    let Some(selection) = editor.selection.clone() else {
        return Ok(());
    };
    let props = arg(args, 0)?
        .as_object()
        .ok_or_else(|| "setPoint properties are not an object".to_string())?;
    let options = args.get(1).and_then(Value::as_object);
    let edge = options
        .and_then(|options| options.get("edge"))
        .and_then(Value::as_str)
        .unwrap_or("focus");

    let mut point = match edge {
        "anchor" => selection.anchor.clone(),
        "start" => selection.start().clone(),
        "end" => selection.end().clone(),
        _ => selection.focus.clone(),
    };
    if let Some(path) = props.get("path") {
        point.path = as_path(path)?;
    }
    if let Some(offset) = props.get("offset").and_then(Value::as_u64) {
        point.offset = offset as usize;
    }

    editor.selection = Some(match edge {
        "anchor" => Range::new(point, selection.focus.clone()),
        "focus" => Range::new(selection.anchor.clone(), point),
        "start" => {
            if selection.is_backward() {
                Range::new(selection.anchor.clone(), point)
            } else {
                Range::new(point, selection.focus.clone())
            }
        }
        "end" => {
            if selection.is_backward() {
                Range::new(point, selection.focus.clone())
            } else {
                Range::new(selection.anchor.clone(), point)
            }
        }
        _ => return Err(unsupported("setPoint edge option")),
    });
    Ok(())
}

fn replay_move_selection(editor: &mut Editor, args: &[Value]) -> Result<(), String> {
    let Some(selection) = editor.selection.clone() else {
        return Ok(());
    };
    let options = args.first().and_then(Value::as_object);
    let reverse = options
        .and_then(|options| options.get("reverse"))
        .and_then(Value::as_bool)
        .unwrap_or(false);
    let distance = options
        .and_then(|options| options.get("distance"))
        .and_then(Value::as_u64)
        .unwrap_or(1) as usize;
    let word = match options
        .and_then(|options| options.get("unit"))
        .and_then(Value::as_str)
    {
        None | Some("character") => false,
        Some("word") => true,
        Some(_) => return Err(unsupported("move unit line/block")),
    };
    let edge = options
        .and_then(|options| options.get("edge"))
        .and_then(Value::as_str);

    let backward = selection.is_backward();
    let edge = match edge {
        Some("start") => Some(if backward { "focus" } else { "anchor" }),
        Some("end") => Some(if backward { "anchor" } else { "focus" }),
        other => other,
    };

    let move_point = |point: &Point| step_point(editor, point, !reverse, word, distance);
    let mut next = selection.clone();
    if edge.is_none() || edge == Some("anchor") {
        next.anchor = move_point(&selection.anchor);
    }
    if edge.is_none() || edge == Some("focus") {
        next.focus = move_point(&selection.focus);
    }
    if !matches!(edge, None | Some("anchor") | Some("focus")) {
        return Err(unsupported("move edge option"));
    }

    editor.selection = Some(next);
    Ok(())
}

fn step_point(editor: &Editor, point: &Point, forward: bool, word: bool, distance: usize) -> Point {
    let mut point = point.clone();
    for _ in 0..distance {
        let Some(text) = editor.text(&point.path) else {
            break;
        };
        let len = text.len();
        if forward {
            if point.offset < len {
                point.offset = if word {
                    word_end_after(&text.text, point.offset)
                } else {
                    grapheme_end_after(&text.text, point.offset)
                };
            } else if let Some(next) = next_text_path(editor, &point.path) {
                point.path = next;
                point.offset = 0;
            } else {
                break;
            }
        } else if point.offset > 0 {
            point.offset = if word {
                word_start_before(&text.text, point.offset)
            } else {
                grapheme_start_before(&text.text, point.offset)
            };
        } else if let Some(previous) = previous_text_path(editor, &point.path) {
            point.path = previous;
            point.offset = editor.text_len_at(&point.path).unwrap_or(0);
        } else {
            break;
        }
    }
    point
}

fn text_entries(editor: &Editor) -> Vec<(Vec<usize>, usize)> {
    fn walk(children: &[Node], prefix: &mut Vec<usize>, out: &mut Vec<(Vec<usize>, usize)>) {
        for (index, child) in children.iter().enumerate() {
            prefix.push(index);
            match child {
                Node::Text(text) => out.push((prefix.clone(), text.len())),
                Node::Element(element) => walk(&element.children, prefix, out),
            }
            prefix.pop();
        }
    }

    let mut out = Vec::new();
    walk(&editor.children, &mut Vec::new(), &mut out);
    out
}

fn next_text_path(editor: &Editor, path: &[usize]) -> Option<Vec<usize>> {
    let entries = text_entries(editor);
    let index = entries
        .iter()
        .position(|(candidate, _)| candidate == path)?;
    entries[index + 1..]
        .iter()
        .find(|(candidate, _)| is_path_selectable(editor, candidate))
        .map(|(candidate, _)| candidate.clone())
}

fn previous_text_path(editor: &Editor, path: &[usize]) -> Option<Vec<usize>> {
    let entries = text_entries(editor);
    let index = entries
        .iter()
        .position(|(candidate, _)| candidate == path)?;
    entries[..index]
        .iter()
        .rev()
        .find(|(candidate, _)| is_path_selectable(editor, candidate))
        .map(|(candidate, _)| candidate.clone())
}

fn is_path_selectable(editor: &Editor, path: &[usize]) -> bool {
    (1..path.len()).all(|depth| {
        editor.element(&path[..depth]).is_none_or(|element| {
            element.properties.get("nonSelectable") != Some(&Value::Bool(true))
        })
    })
}

fn replay_lift_nodes(editor: &mut Editor, args: &[Value]) -> Result<(), String> {
    let options = args.first().and_then(Value::as_object);
    let property = options
        .and_then(|options| options.get("match"))
        .and_then(|value| value.get("__fn"))
        .and_then(Value::as_str)
        .and_then(|source| {
            if source.contains("n.c") || source.contains("node.c") {
                Some("c")
            } else {
                None
            }
        });

    let paths = if let Some(at) = options.and_then(|options| options.get("at")) {
        if at.is_array() {
            vec![as_path(at)?]
        } else {
            let point = as_point(at)?;
            if let Some(property) = property {
                (1..point.path.len())
                    .rev()
                    .find_map(|depth| {
                        let path = point.path[..depth].to_vec();
                        editor
                            .element(&path)
                            .is_some_and(|element| element.properties.get(property).is_some())
                            .then_some(path)
                    })
                    .map(|path| vec![path])
                    .ok_or_else(|| unsupported("liftNodes match predicate"))?
            } else {
                vec![
                    editor
                        .leaf_block_path(&point)
                        .ok_or_else(|| unsupported("liftNodes point outside a block"))?,
                ]
            }
        }
    } else {
        let range = editor
            .selection
            .clone()
            .ok_or_else(|| unsupported("liftNodes without a selection"))?;
        collect_lift_matches(editor, &range, property)
    };

    for path in paths.into_iter().rev() {
        if path.len() < 2 {
            return Err(unsupported("liftNodes at a root-level node"));
        }
        lift_one(editor, &path);
    }
    Ok(())
}

fn collect_lift_matches(editor: &Editor, range: &Range, property: Option<&str>) -> Vec<Vec<usize>> {
    fn subtree_intersects(editor: &Editor, path: &[usize], range: &Range) -> bool {
        let Some(start) = editor.first_text_point_in(path) else {
            return false;
        };
        let Some(end) = editor.last_text_point_in(path) else {
            return false;
        };
        start.compare(range.end()) != Ordering::Greater
            && end.compare(range.start()) != Ordering::Less
    }

    fn visit(
        editor: &Editor,
        path: &[usize],
        range: &Range,
        property: Option<&str>,
        out: &mut Vec<Vec<usize>>,
    ) {
        if !path.is_empty() && !subtree_intersects(editor, path, range) {
            return;
        }
        if path.is_empty() {
            let mut children = Vec::new();
            if let Some(root) = editor.children_at(path) {
                for index in 0..root.len() {
                    visit(
                        editor,
                        &child_path(path, index),
                        range,
                        property,
                        &mut children,
                    );
                }
            }
            out.extend(children);
            return;
        }
        let Some(element) = editor.element(path) else {
            return;
        };
        let matches_self = if let Some(property) = property {
            element.properties.get(property).is_some()
        } else {
            !editor.is_inline_element(element)
        };
        let mut children = Vec::new();
        for index in 0..element.children.len() {
            visit(
                editor,
                &child_path(path, index),
                range,
                property,
                &mut children,
            );
        }
        if children.is_empty() {
            if matches_self {
                out.push(path.to_vec());
            }
        } else {
            out.extend(children);
        }
    }

    let mut matches = Vec::new();
    visit(editor, &[], range, property, &mut matches);
    matches
}

fn lift_one(editor: &mut Editor, path: &[usize]) {
    let parent_path = path[..path.len() - 1].to_vec();
    let index = *path.last().unwrap();
    let length = editor
        .element(&parent_path)
        .map(|parent| parent.children.len())
        .unwrap_or(0);

    if length == 1 {
        let to = path::next(&parent_path);
        editor.move_nodes(path, &to);
        editor.remove_nodes(&parent_path, 1);
    } else if index == 0 {
        editor.move_nodes(path, &parent_path);
    } else if index + 1 == length {
        let to = path::next(&parent_path);
        editor.move_nodes(path, &to);
    } else {
        let Some(parent) = editor.element(&parent_path).cloned() else {
            return;
        };
        let lifted = parent.children[index].clone();
        let before = parent.children[..index].to_vec();
        let after = parent.children[index + 1..].to_vec();
        let parent_index = *parent_path.last().unwrap();
        let grandparent = parent_path[..parent_path.len() - 1].to_vec();
        editor.transaction(|editor| {
            editor.remove_nodes(path, 1);
            editor.remove_nodes(&child_path(&parent_path, index), after.len());
            let mut after_parent = parent.clone();
            after_parent.children = after.clone();
            editor.insert_nodes(&child_path(&grandparent, parent_index + 1), vec![lifted]);
            if !after.is_empty() {
                editor.insert_nodes(
                    &child_path(&grandparent, parent_index + 2),
                    vec![Node::Element(after_parent)],
                );
            }
        });
        let _ = before;
    }
}

fn child_path(parent: &[usize], index: usize) -> Vec<usize> {
    let mut path = parent.to_vec();
    path.push(index);
    path
}

fn arg(args: &[Value], index: usize) -> Result<&Value, String> {
    args.get(index)
        .ok_or_else(|| format!("call is missing argument {index}"))
}

fn arg_str(args: &[Value], index: usize) -> Result<&str, String> {
    arg(args, index)?
        .as_str()
        .ok_or_else(|| format!("argument {index} is not a string"))
}

fn unsupported(reason: impl Into<String>) -> String {
    format!("UNSUPPORTED: {}", reason.into())
}

fn eval_call(call: &Call) -> Result<Value, String> {
    let args = &call.args;
    let arg = |index: usize| -> Result<&Value, String> {
        args.get(index).ok_or_else(|| {
            format!(
                "{}::{} is missing argument {index}",
                call.target, call.method
            )
        })
    };

    match (call.target.as_str(), call.method.as_str()) {
        ("Path", "ancestors") => {
            let path = as_path(arg(0)?)?;
            let reverse = option_bool(args, 1, "reverse");
            Ok(json!(path::ancestors_with(&path, reverse)))
        }
        ("Path", "common") => Ok(json!(path::common(&as_path(arg(0)?)?, &as_path(arg(1)?)?))),
        ("Path", "compare") => Ok(json!(as_ordering(&path::compare(
            &as_path(arg(0)?)?,
            &as_path(arg(1)?)?,
        )))),
        ("Path", "endsAfter") => Ok(json!(path::ends_after(
            &as_path(arg(0)?)?,
            &as_path(arg(1)?)?,
        ))),
        ("Path", "endsAt") => Ok(json!(
            path::ends_at(&as_path(arg(0)?)?, &as_path(arg(1)?)?,)
        )),
        ("Path", "endsBefore") => Ok(json!(path::ends_before(
            &as_path(arg(0)?)?,
            &as_path(arg(1)?)?,
        ))),
        ("Path", "equals") => Ok(json!(path::equals(&as_path(arg(0)?)?, &as_path(arg(1)?)?,))),
        ("Path", "hasPrevious") => Ok(json!(path::has_previous(&as_path(arg(0)?)?))),
        ("Path", "isAfter") => Ok(json!(path::is_after(
            &as_path(arg(0)?)?,
            &as_path(arg(1)?)?,
        ))),
        ("Path", "isAncestor") => Ok(json!(path::is_ancestor(
            &as_path(arg(0)?)?,
            &as_path(arg(1)?)?,
        ))),
        ("Path", "isBefore") => Ok(json!(path::is_before(
            &as_path(arg(0)?)?,
            &as_path(arg(1)?)?,
        ))),
        ("Path", "isChild") => Ok(json!(path::is_child(
            &as_path(arg(0)?)?,
            &as_path(arg(1)?)?,
        ))),
        ("Path", "isDescendant") => Ok(json!(path::is_descendant(
            &as_path(arg(0)?)?,
            &as_path(arg(1)?)?,
        ))),
        ("Path", "isParent") => Ok(json!(path::is_parent(
            &as_path(arg(0)?)?,
            &as_path(arg(1)?)?,
        ))),
        ("Path", "isPath") => Ok(json!(path::is_path(arg(0)?))),
        ("Path", "isSibling") => Ok(json!(path::is_sibling(
            &as_path(arg(0)?)?,
            &as_path(arg(1)?)?,
        ))),
        ("Path", "levels") => {
            let path = as_path(arg(0)?)?;
            let reverse = option_bool(args, 1, "reverse");
            Ok(json!(path::levels_with(&path, reverse)))
        }
        ("Path", "next") => Ok(json!(path::next(&as_path(arg(0)?)?))),
        ("Path", "parent") => Ok(json!(path::parent(&as_path(arg(0)?)?))),
        ("Path", "previous") => Ok(json!(path::previous(&as_path(arg(0)?)?))),
        ("Path", "relative") => Ok(json!(path::relative(
            &as_path(arg(0)?)?,
            &as_path(arg(1)?)?,
        ))),
        ("Path", "transform") => {
            let path = as_path(arg(0)?)?;
            let operation = as_operation(arg(1)?)?;
            let affinity = option_affinity(args, 2);
            Ok(json!(path::transform_with_affinity(
                &path, &operation, affinity
            )))
        }

        ("Point", "compare") => Ok(json!(as_ordering(
            &as_point(arg(0)?)?.compare(&as_point(arg(1)?)?)
        ))),
        ("Point", "equals") => Ok(json!(as_point(arg(0)?)?.equals(&as_point(arg(1)?)?))),
        ("Point", "isAfter") => Ok(json!(as_point(arg(0)?)?.is_after(&as_point(arg(1)?)?))),
        ("Point", "isBefore") => Ok(json!(as_point(arg(0)?)?.is_before(&as_point(arg(1)?)?))),
        ("Point", "isPoint") => Ok(json!(Point::is_point(arg(0)?))),
        ("Point", "transform") => {
            let point = as_point(arg(0)?)?;
            let operation = as_operation(arg(1)?)?;
            let affinity = option_affinity(args, 2);
            Ok(json!(point.transform(&operation, affinity)))
        }

        ("Range", "direction") => {
            let direction = as_range(arg(0)?)?.direction();
            Ok(json!(match direction {
                RangeDirection::Forward => "forward",
                RangeDirection::Backward => "backward",
                RangeDirection::Collapsed => "collapsed",
            }))
        }
        ("Range", "edges") => {
            let range = as_range(arg(0)?)?;
            let reverse = option_bool(args, 1, "reverse");
            let (start, end) = range.edges_with(reverse);
            Ok(json!([start, end]))
        }
        ("Range", "equals") => Ok(json!(as_range(arg(0)?)?.equals(&as_range(arg(1)?)?))),
        ("Range", "includes") => Ok(json!(as_range(arg(0)?)?.includes(&as_location(arg(1)?)?))),
        ("Range", "isBackward") => Ok(json!(as_range(arg(0)?)?.is_backward())),
        ("Range", "isCollapsed") => Ok(json!(as_range(arg(0)?)?.is_collapsed())),
        ("Range", "isExpanded") => Ok(json!(as_range(arg(0)?)?.is_expanded())),
        ("Range", "isForward") => Ok(json!(as_range(arg(0)?)?.is_forward())),
        ("Range", "isRange") => Ok(json!(Range::is_range(arg(0)?))),
        ("Range", "points") => {
            let range = as_range(arg(0)?)?;
            let points = range.points();
            Ok(json!([
                [points[0].0.clone(), points[0].1],
                [points[1].0.clone(), points[1].1]
            ]))
        }
        ("Range", "start") => Ok(json!(as_range(arg(0)?)?.start())),
        ("Range", "end") => Ok(json!(as_range(arg(0)?)?.end())),
        ("Range", "transform") => {
            let range = as_range(arg(0)?)?;
            let operation = as_operation(arg(1)?)?;
            let affinity = option_range_affinity(args, 2);
            Ok(json!(range.transform_with_affinity(&operation, affinity)))
        }

        (target, method) => Err(format!(
            "no Rust mapping for {target}::{method} (args: {})",
            serde_json::to_string(args).unwrap()
        )),
    }
}

fn as_path(value: &Value) -> Result<path::Path, String> {
    serde_json::from_value(value.clone()).map_err(|error| format!("invalid path: {error}"))
}

fn as_point(value: &Value) -> Result<Point, String> {
    serde_json::from_value(value.clone()).map_err(|error| format!("invalid point: {error}"))
}

fn as_range(value: &Value) -> Result<Range, String> {
    serde_json::from_value(value.clone()).map_err(|error| format!("invalid range: {error}"))
}

fn as_operation(value: &Value) -> Result<Operation, String> {
    serde_json::from_value(value.clone()).map_err(|error| format!("invalid operation: {error}"))
}

fn as_location(value: &Value) -> Result<Location, String> {
    if value.is_array() {
        return Ok(Location::Path(as_path(value)?));
    }
    if value.get("anchor").is_some() || value.get("focus").is_some() {
        return Ok(Location::Range(as_range(value)?));
    }
    Ok(Location::Point(as_point(value)?))
}

fn as_ordering(ordering: &Ordering) -> i32 {
    match ordering {
        Ordering::Less => -1,
        Ordering::Equal => 0,
        Ordering::Greater => 1,
    }
}

fn option(args: &[Value], index: usize, key: &str) -> Option<Value> {
    args.get(index)?.as_object()?.get(key).cloned()
}

fn option_bool(args: &[Value], index: usize, key: &str) -> bool {
    option(args, index, key)
        .and_then(|value| value.as_bool())
        .unwrap_or(false)
}

fn option_affinity(args: &[Value], index: usize) -> leptoslate_core::Affinity {
    match option(args, index, "affinity")
        .as_ref()
        .and_then(Value::as_str)
    {
        Some("backward") => leptoslate_core::Affinity::Backward,
        _ => leptoslate_core::Affinity::Forward,
    }
}

fn option_range_affinity(args: &[Value], index: usize) -> RangeAffinity {
    match option(args, index, "affinity")
        .as_ref()
        .and_then(Value::as_str)
    {
        Some("outward") => RangeAffinity::Outward,
        Some("forward") => RangeAffinity::Forward,
        Some("backward") => RangeAffinity::Backward,
        _ => RangeAffinity::Inward,
    }
}

fn collect_json(directory: &FsPath, files: &mut Vec<PathBuf>) {
    let Ok(entries) = fs::read_dir(directory) else {
        return;
    };
    for entry in entries.flatten() {
        let path = entry.path();
        if path.is_dir() {
            collect_json(&path, files);
        } else if path
            .extension()
            .is_some_and(|extension| extension == "json")
        {
            files.push(path);
        }
    }
}
